INSERT INTO public.products (name, slug, category_id, short_description, long_description, image_url, features, applications, cta_text, cta_link, seo_title, seo_description, status, sort_order) VALUES
('CoreIP Vaani-101P','coreip-vaani-101p',(SELECT id FROM public.product_categories WHERE slug='ip-phones'),'Entry-level CoreIP Vaani IP phone for everyday enterprise desks.','The CoreIP Vaani-101P is part of the CoreIP Vaani IP phone range, designed for enterprise desk deployments on CoreIP unified communication platforms.','/media/vaani-101P.png','{"HD voice","PoE support","Provisioning at scale"}','{"Enterprise desks","Reception","Campus deployments"}','Request a Quote','/contact','CoreIP Vaani-101P IP Phone','Entry-level CoreIP Vaani-101P IP phone for enterprise desk deployments on CoreIP unified communication platforms.','published',1),
('CoreIP Vaani-102P','coreip-vaani-102p',(SELECT id FROM public.product_categories WHERE slug='ip-phones'),'CoreIP Vaani IP phone for enterprise desk and reception use.','The CoreIP Vaani-102P belongs to the CoreIP Vaani IP phone family used across enterprise and institutional deployments.','/media/vaani-101P.png','{"HD voice","PoE support","Multi-line support"}','{"Enterprise desks","Reception"}','Request a Quote','/contact','CoreIP Vaani-102P IP Phone','CoreIP Vaani-102P IP phone for enterprise desk and reception deployments.','published',2),
('CoreIP Vaani-102G','coreip-vaani-102g',(SELECT id FROM public.product_categories WHERE slug='ip-phones'),'Gigabit variant of the CoreIP Vaani IP phone range.','The CoreIP Vaani-102G is the gigabit variant in the CoreIP Vaani IP phone range for enterprise networks.','/media/vaani-101P.png','{"HD voice","Gigabit ports","PoE support"}','{"Enterprise desks","Gigabit networks"}','Request a Quote','/contact','CoreIP Vaani-102G IP Phone','CoreIP Vaani-102G gigabit IP phone for enterprise networks.','published',3),
('CoreIP T23G','coreip-t23g',(SELECT id FROM public.product_categories WHERE slug='ip-phones'),'CoreIP T-series IP phone for high-volume desk deployments.','The CoreIP T23G is part of the CoreIP T-series IP phone range offered for enterprise deployments.','/media/IP-Phones.jpg','{"HD voice","Gigabit ports","Multi-line support"}','{"Enterprise desks","Call centres"}','Request a Quote','/contact','CoreIP T23G IP Phone','CoreIP T23G IP phone for enterprise desk deployments.','published',4),
('CoreIP T43U','coreip-t43u',(SELECT id FROM public.product_categories WHERE slug='ip-phones'),'CoreIP T-series IP phone with USB support for professional users.','The CoreIP T43U is part of the CoreIP T-series IP phone range for professional enterprise users.','/media/IP-Phones.jpg','{"HD voice","USB support","Gigabit ports"}','{"Managers","Professional users"}','Request a Quote','/contact','CoreIP T43U IP Phone','CoreIP T43U IP phone with USB support for professional enterprise users.','published',5),
('CoreIP T46U','coreip-t46u',(SELECT id FROM public.product_categories WHERE slug='ip-phones'),'CoreIP T-series executive IP phone with large display.','The CoreIP T46U is an executive model in the CoreIP T-series IP phone range.','/media/IP-Phones.jpg','{"HD voice","Large display","USB support"}','{"Executives","Management desks"}','Request a Quote','/contact','CoreIP T46U IP Phone','CoreIP T46U executive IP phone with large display.','published',6),
('CoreIP T-58W','coreip-t-58w',(SELECT id FROM public.product_categories WHERE slug='ip-phones'),'Smart CoreIP IP phone with touch display for executive desks.','The CoreIP T-58W is a smart IP phone in the CoreIP range, intended for executive and collaboration-focused desks.','/media/IP-Phones.jpg','{"Touch display","HD voice","Wireless connectivity"}','{"Executive desks","Collaboration rooms"}','Request a Quote','/contact','CoreIP T-58W Smart IP Phone','CoreIP T-58W smart IP phone with touch display for executive desks.','published',7),
('CoreIP T-58W PRO','coreip-t-58w-pro',(SELECT id FROM public.product_categories WHERE slug='ip-phones'),'Top-of-range smart CoreIP IP phone for executive collaboration.','The CoreIP T-58W PRO is the top-of-range smart IP phone in the CoreIP portfolio for executive collaboration.','/media/IP-Phones.jpg','{"Touch display","HD voice","Video capable","Wireless connectivity"}','{"Executive desks","Video collaboration"}','Request a Quote','/contact','CoreIP T-58W PRO Smart IP Phone','CoreIP T-58W PRO smart IP phone for executive collaboration.','published',8),
('Unified Communication Server','unified-communication-server',(SELECT id FROM public.product_categories WHERE slug='communication'),'The core of enterprise voice, video and messaging on a single platform.','CoreIP Unified Communication Server delivers IPPBX telephony, conferencing and collaboration on a single platform and has been deployed at scale across government and enterprise organisations.','/media/unified_communication-2.jpg','{"IPPBX telephony","Conferencing","Scales to 5000+ lines"}','{"Government","Enterprise","Campus"}','Talk to an Expert','/contact','CoreIP Unified Communication Server','CoreIP Unified Communication Server for enterprise voice, video and messaging, scaling to 5000+ lines.','published',9),
('UCX on Cloud','ucx-on-cloud',(SELECT id FROM public.product_categories WHERE slug='communication'),'Hosted unified communication for distributed and multi-site organisations.','CoreIP UCX on Cloud delivers hosted unified communication for multi-site organisations, with site-to-site dialling and elastic capacity.','/media/ucx_on_cloud.jpg','{"Cloud delivered","Site-to-site dialling","Elastic capacity"}','{"Multi-site enterprises","Distributed teams"}','Request a Demo','/contact','CoreIP UCX on Cloud','Hosted CoreIP UCX unified communication for distributed and multi-site organisations.','published',10),
('CoreIP NMS','coreip-nms',(SELECT id FROM public.product_categories WHERE slug='networking'),'Network management with complete visibility of devices, links and performance.','CoreIP NMS is a network management and monitoring product providing visibility of network devices, links and performance from a central console.','/media/netword-management.jpg','{"Topology view","Performance graphs","Alerting","Device management"}','{"Enterprise networks","Campus networks","Data centres"}','Explore NMS','/contact','CoreIP NMS — Network Management Software','CoreIP NMS network management software with topology view, performance monitoring and alerting.','published',11),
('CoreIP UVMS','coreip-uvms',(SELECT id FROM public.product_categories WHERE slug='security'),'Unified video management for centralised surveillance operations.','CoreIP UVMS (Unified Video Management Server) centralises multi-site video surveillance, recording and monitoring in a single console.','/media/video-management-system.jpg','{"Multi-site video","Recording","Central console"}','{"Surveillance operations","Multi-site premises"}','Talk to an Expert','/contact','CoreIP UVMS — Unified Video Management Server','CoreIP UVMS unified video management server for centralised, multi-site surveillance operations.','published',12),
('VMS / VA / FRS','vms-va-frs',(SELECT id FROM public.product_categories WHERE slug='security'),'Video management, video analytics and face recognition on one platform.','CoreIP VMS / VA / FRS combines video management, video analytics and face recognition capabilities for security-driven deployments.','/media/NVS_coreip.jpg','{"Video management","Video analytics","Face recognition"}','{"Security operations","Access control","Public safety"}','Talk to an Expert','/contact','CoreIP VMS / VA / FRS','CoreIP VMS, video analytics and face recognition platform for security-driven deployments.','published',13),
('CoreIP UMGW','coreip-umgw',(SELECT id FROM public.product_categories WHERE slug='media-gateways'),'CoreIP unified media gateway bridging telecom lines into IP.','CoreIP UMGW is a unified media gateway that connects analog and digital telecom lines into an IP communication core.','/media/8FXS.png','{"Analog & digital ports","Trunk failover","SIP interworking"}','{"Legacy telecom migration","Trunk integration"}','Request a Quote','/contact','CoreIP UMGW Unified Media Gateway','CoreIP UMGW unified media gateway connecting analog and digital telecom lines into an IP core.','published',14),
('Media Gateways','media-gateways-product',(SELECT id FROM public.product_categories WHERE slug='media-gateways'),'Bridge PRI, FXO and FXS telecom lines into an IP communication core.','CoreIP media gateways bridge PRI, FXO and FXS telecom lines into an IP communication core with trunk failover and SIP interworking.','/media/media_gateway.jpg','{"PRI / FXO / FXS ports","Trunk failover","SIP interworking"}','{"Telecom integration","Hybrid communication"}','Request a Quote','/contact','CoreIP Media Gateways','CoreIP media gateways for PRI, FXO and FXS telecom integration with IP communication cores.','published',15),
('CoreIP UCS-1000RPS','coreip-ucs-1000rps',(SELECT id FROM public.product_categories WHERE slug='servers'),'CoreIP unified communication server hardware with redundant power.','CoreIP UCS-1000RPS is a server platform configured for CoreIP unified communication workloads with redundant power supply.','/media/server.png','{"Redundant power supply","Rack form factor","Communication workload sizing"}','{"Unified communication","On-premise deployments"}','Request a Quote','/contact','CoreIP UCS-1000RPS Server','CoreIP UCS-1000RPS unified communication server platform with redundant power supply.','published',16),
('Industrial Grade COTS Servers','industrial-grade-cots-servers',(SELECT id FROM public.product_categories WHERE slug='servers'),'Commercial off-the-shelf server platforms for demanding environments.','CoreIP industrial grade COTS servers are commercial off-the-shelf server platforms configured for communication, video and application workloads.','/media/server-1.png','{"Rack form factors","Workload sizing","On-site support"}','{"Communication workloads","Video workloads","Application hosting"}','Request a Quote','/contact','Industrial Grade COTS Servers — CoreIP','CoreIP industrial grade COTS servers for communication, video and application workloads.','published',17),
('CoreIP UNAS','coreip-unas',(SELECT id FROM public.product_categories WHERE slug='storage'),'Unified network attached storage for recordings, archives and data.','CoreIP UNAS is unified network attached storage for video recordings, archives and enterprise data, with expandable capacity and RAID protection.','/media/coreip-UNAS.png','{"Expandable capacity","RAID protection","Network shares"}','{"Video archives","Enterprise data","Backup"}','Request a Quote','/contact','CoreIP UNAS — Unified Network Attached Storage','CoreIP UNAS unified network attached storage with expandable capacity and RAID protection.','published',18),
('Call Billing Software','call-billing-software',(SELECT id FROM public.product_categories WHERE slug='software'),'Accurate call accounting and cost control across extensions and trunks.','CoreIP Call Billing Software provides call detail records, department-wise billing and usage reporting for accurate call accounting and cost control.','/media/call_biling.jpg','{"Call detail records","Department-wise billing","Usage reports"}','{"Cost control","Telecom accounting"}','Request a Demo','/contact','CoreIP Call Billing Software','CoreIP call billing software with call detail records, department-wise billing and usage reports.','published',19),
('Complaint Management System','complaint-management-system',(SELECT id FROM public.product_categories WHERE slug='software'),'Structured complaint logging, assignment and closure for service teams.','CoreIP Complaint Management System provides structured complaint logging, assignment, escalation and closure for service-driven teams.','/media/Complaint-management-system.jpg','{"Ticket lifecycle","Escalation flow","ISO-aligned records"}','{"Service desks","Support teams","Facility management"}','Request a Demo','/contact','CoreIP Complaint Management System','CoreIP complaint management system with ticket lifecycle, escalation flow and ISO-aligned records.','published',20);
INSERT INTO public.services (name, slug, category, icon, short_description, long_description, hero_image_url, features, benefits, cta_text, cta_link, seo_title, seo_description, status, sort_order, featured) VALUES
('Unified Communication','unified-communication','Communication','phone','IPPBX, VoIP, video conferencing and collaboration on CoreIP''s UCX platform.','CoreIP delivers unified communication across IPPBX, VoIP, video conferencing and collaboration — on premise or on cloud — built on the CoreIP UCX platform.','/media/unified_communication-2.jpg','{"IPPBX / VoIP","Video conferencing","UCX on Cloud"}','{"Single communication platform","Scales to thousands of lines","On premise or cloud"}','Talk to an Expert','/contact','Unified Communication Solutions — CoreIP','CoreIP unified communication solutions: IPPBX, VoIP, video conferencing and collaboration on premise or on cloud.','published',1,true),
('Security Solutions','security-solutions','Security','shield','Surveillance, access and video management deployments.','CoreIP security solutions cover surveillance, access and video management deployments that protect people, premises and information.','/media/video-management-system.jpg','{"Video management (UVMS)","Access & surveillance","Helpline platforms"}','{"Centralised monitoring","Multi-site coverage","Mission-critical reliability"}','Talk to an Expert','/contact','Security Solutions — CoreIP','CoreIP security solutions covering surveillance, access control and unified video management.','published',2,true),
('Networking Solutions','networking-solutions','Networking','network','Structured, resilient enterprise networks with centralised monitoring.','CoreIP designs structured, resilient enterprise networks with centralised monitoring and device management through CoreIP NMS.','/media/netword-management.jpg','{"LAN / WAN design","Network monitoring","Device management"}','{"Resilient connectivity","Central visibility","Faster fault resolution"}','Talk to an Expert','/contact','Networking Solutions — CoreIP','CoreIP networking solutions: LAN/WAN design, network monitoring and device management.','published',3,true),
('Telecom Solutions','telecom-solutions','Telecom','radio','Media gateways, trunking and call management for hybrid telecom.','CoreIP telecom solutions connect legacy telecom with modern IP infrastructure using media gateways, trunk integration and call management.','/media/media_gateway.jpg','{"Media gateways","Call billing","Trunk integration"}','{"Protects existing investment","Hybrid migration path","Cost visibility"}','Talk to an Expert','/contact','Telecom Solutions — CoreIP','CoreIP telecom solutions with media gateways, trunk integration and call billing.','published',4,true),
('Hosting Solutions','hosting-solutions','Hosting','cloud','Servers, storage and hosted communication infrastructure.','CoreIP hosting solutions provide servers, storage and hosted communication infrastructure sized for enterprise and government workloads.','/media/server.png','{"COTS servers","UNAS storage","Hosted UCX"}','{"Right-sized capacity","Expandable storage","Managed infrastructure"}','Talk to an Expert','/contact','Hosting Solutions — CoreIP','CoreIP hosting solutions: COTS servers, UNAS storage and hosted UCX communication.','published',5,true),
('Video Conferencing','video-conferencing','Communication','video','Meeting-room and desktop video collaboration for distributed teams.','CoreIP video conferencing brings meeting-room and desktop video collaboration to distributed organisations as part of the unified communication platform.','/media/ucx_on_cloud.jpg','{"Room and desktop video","Multi-party conferencing","Cloud or on premise"}','{"Faster decisions","Lower travel cost","Consistent experience"}','Request a Demo','/contact','Video Conferencing Solutions — CoreIP','CoreIP video conferencing for meeting rooms and desktops, on cloud or on premise.','published',6,false),
('Network Management','network-management','Networking','activity','Centralised monitoring of devices, links and performance.','CoreIP network management, delivered through CoreIP NMS, gives centralised visibility of devices, links and performance across the enterprise network.','/media/nms-dashboard.jpg','{"Topology view","Performance monitoring","Alerting"}','{"Proactive fault detection","Single pane of glass","Better uptime"}','Explore NMS','/contact','Network Management — CoreIP','Centralised network management and monitoring with CoreIP NMS.','published',7,false),
('Enterprise Hardware','enterprise-hardware','Hardware','server','Servers, storage and communication hardware for enterprise workloads.','CoreIP supplies and supports enterprise hardware — servers, storage and communication appliances — configured for the workloads they run.','/media/server-1.png','{"COTS and industrial servers","UNAS storage","Media gateways"}','{"Workload-matched sizing","Warranty support","On-site service"}','Request a Quote','/contact','Enterprise Hardware — CoreIP','CoreIP enterprise hardware: servers, storage and communication appliances.','published',8,false);
