INSERT INTO public.faqs (question, answer, category, sort_order) VALUES
('What does CoreIP do?','CoreIP designs, deploys and supports unified communication, networking, security, telecom and hosting infrastructure for enterprises, institutions and government organisations.','Company',1),
('Which IP phones does CoreIP provide?','CoreIP provides the Vaani range (Vaani-101P, Vaani-102P, Vaani-102G) and the T-series (T23G, T43U, T46U, T-58W and T-58W PRO).','Products',2),
('What is CoreIP NMS?','CoreIP NMS is network management software that gives centralised visibility of network devices, links and performance, with topology views, performance graphs and alerting.','Products',3),
('What is UCX?','UCX is CoreIP''s unified communication platform, available on premise through the Unified Communication Server or hosted as UCX on Cloud.','Products',4),
('What is VMS / VA / FRS?','VMS / VA / FRS is CoreIP''s combined video management, video analytics and face recognition offering for security-driven deployments.','Products',5),
('Which servers does CoreIP provide?','CoreIP provides the UCS-1000RPS server platform and industrial grade COTS servers configured for communication, video and application workloads.','Products',6),
('Which industries does CoreIP serve?','CoreIP serves manufacturing, warehousing, healthcare, retail, hospitality and education, alongside government and institutional customers.','Company',7),
('How can I request a demo or quote?','Use the Request a Quote form on any product or solution page, or contact the CoreIP team by phone or email from the Contact page.','Support',8);
INSERT INTO public.knowledge_articles (title, category, content, keywords, link_url, link_label) VALUES
('About CoreIP','Company','CoreIP is an enterprise technology company that designs, deploys and supports unified communication, networking, security, telecom and hosting infrastructure. CoreIP has delivered large-scale communication deployments for government and enterprise organisations including Railway Board, NBCC, NTPC and IIM.','{"about","company","coreip","who"}','/about','About CoreIP'),
('Contacting CoreIP','Contact','You can reach CoreIP at +91-120-6618000 or +91-120-6618005, by email at info@coreip.co.in, or at C-421, The iThum, A-40, Sector-62, Noida 201309, Uttar Pradesh, India. You can also submit the contact form on the website.','{"contact","phone","email","address","reach","support"}','/contact','Contact CoreIP'),
('CoreIP IP Phones','Products','CoreIP offers the Vaani IP phone range (Vaani-101P, Vaani-102P and the gigabit Vaani-102G) and the T-series (T23G, T43U, T46U, T-58W and T-58W PRO) for desks, reception and executive use, with HD voice, PoE support and provisioning at scale.','{"ip phone","phones","vaani","t23g","t43u","t46u","t58w","desk phone"}','/products/ip-phones','Explore IP Phones'),
('CoreIP NMS','Products','CoreIP NMS is network management software providing complete visibility of network devices, links and performance, including topology views, performance graphs, alerting and device management.','{"nms","network management","monitoring","topology"}','/products/networking/coreip-nms','Explore CoreIP NMS'),
('CoreIP UVMS','Products','CoreIP UVMS (Unified Video Management Server) centralises multi-site video surveillance, recording and monitoring in a single console.','{"uvms","video management","surveillance","cctv"}','/products/security/coreip-uvms','Explore CoreIP UVMS'),
('VMS / VA / FRS','Products','CoreIP VMS / VA / FRS combines video management, video analytics and face recognition capabilities for security operations, access control and public safety deployments.','{"vms","va","frs","video analytics","face recognition"}','/products/security/vms-va-frs','Explore VMS / VA / FRS'),
('Unified Communication Server and UCX','Products','The CoreIP Unified Communication Server delivers IPPBX telephony, conferencing and collaboration on one platform and scales beyond 5000 lines. UCX on Cloud provides the same unified communication hosted for multi-site organisations with site-to-site dialling and elastic capacity.','{"ucx","unified communication","ippbx","voip","cloud","server"}','/products/communication/unified-communication-server','Explore Unified Communication'),
('CoreIP Servers','Products','CoreIP provides the UCS-1000RPS unified communication server platform with redundant power supply, and industrial grade COTS servers configured for communication, video and application workloads.','{"server","ucs-1000rps","cots","hardware","rack"}','/products/servers','Explore Servers'),
('CoreIP UNAS Storage','Products','CoreIP UNAS is unified network attached storage for video recordings, archives and enterprise data, offering expandable capacity, RAID protection and network shares.','{"unas","storage","nas","backup","archive"}','/products/storage/coreip-unas','Explore CoreIP UNAS'),
('CoreIP Media Gateways and UMGW','Products','CoreIP UMGW and the CoreIP media gateway range bridge PRI, FXO and FXS telecom lines into an IP communication core, with trunk failover and SIP interworking.','{"media gateway","umgw","pri","fxo","fxs","trunk","telecom"}','/products/media-gateways','Explore Media Gateways'),
('Call Billing Software','Products','CoreIP Call Billing Software provides call detail records, department-wise billing and usage reports for accurate call accounting and cost control across extensions and trunks.','{"call billing","call accounting","cdr","billing software"}','/products/software/call-billing-software','Explore Call Billing'),
